var HeaderManager=function(){var n=this;n.data={clock:{year:0,month:0,day:0,hour:0,minute:0,second:0,labelAM:"",labelPM:"",months:[]}};n.enums={ErrorCode:{AccessDenied:1}};n.init=function(){n.initClock();n.runClock();n.initElements();n.bindEvents()};n.initClock=function(){var t=$("#clock");n.data.clock.year=t.attr("data-year");n.data.clock.month=t.attr("data-month");n.data.clock.day=t.attr("data-day");n.data.clock.hour=t.attr("data-hour");n.data.clock.minute=t.attr("data-minute");n.data.clock.second=t.attr("data-second");n.data.clock.labelAM=t.attr("data-label-am");n.data.clock.labelPM=t.attr("data-label-pm");n.data.clock.labelMonths=JSON.parse(t.attr("data-label-months").replace(/'/g,'"'))};n.initElements=function(){var n=$("#language").attr("data-currentlanguage"),t=$(".list-language ."+n+" > a").html();$(".language-selector-container").html(t)};n.bindEvents=function(){$(".changelanguage-link").click(function(){n.changeLanguage($(this).attr("data-value"))})};n.runClock=function(){n.data.clock.second++;n.data.clock.second==60&&(n.data.clock.second=0,n.data.clock.minute++);n.data.clock.minute==60&&(n.data.clock.minute=0,n.data.clock.hour++);n.data.clock.hour==24&&(n.data.clock.hour=0,n.data.clock.second=0,n.data.clock.minute=0,n.data.clock.day++);strmin=n.data.clock.minute<10?"0"+n.data.clock.minute:n.data.clock.minute;strsec=n.data.clock.second<10?"0"+n.data.clock.second:n.data.clock.second;_.isDate(new Date(parseFloat(n.data.clock.year)+"/"+n.data.clock.month+"/"+n.data.clock.day))||(n.data.clock.month++,n.data.clock.day=1);_.isDate(new Date(parseFloat(n.data.clock.year)+"/"+n.data.clock.month+"/"+n.data.clock.day))||(n.data.clock.year++,n.data.clock.month=1,n.data.clock.day=1);stra=n.data.clock.hour>=12?n.data.clock.labelPM:n.data.clock.labelAM;strhrs=n.data.clock.hour>=12?n.data.clock.hour-12:n.data.clock.hour;var t=strhrs+":"+strmin+":"+strsec+" "+stra+" "+n.data.clock.labelMonths[n.data.clock.month-1]+" "+n.data.clock.day+", "+n.data.clock.year+" GMT-4";$("#clock").html(t);setTimeout(n.runClock,1e3)};n.changeLanguage=function(t){var i=top.baseMainApp+"Home/ChangeLanguage";jQuery.ajax({type:"POST",url:i,data:{Language:t},responseType:"json",success:function(i){var r=i.ResultCode,u;r==0?(u=window.location.hostname.replace(/([a-zA-Z0-9]+.)/,"").replace("www.",""),setCookie("LANGUAGE",t,30,u),n.reloadPage()):r==n.enums.ErrorCode.AccessDenied&&indexPageManager.signOut()},error:function(){}})};n.reloadPage=function(){top.location=n.removeBookmarksInUrl(top.location.href)};n.removeBookmarksInUrl=function(n){if(typeof n!="string")return null;var t=n.indexOf("#");return t==-1?n:n.substr(0,t)}},headerManager=new HeaderManager;jQuery(document).ready(function(){headerManager.init()});